<?php $reversalQuery=$db->prepare('SELECT state,kind,transaction_id FROM '.Database::table('payment_operations')." WHERE order_id=? AND kind IN ('void','refund') ORDER BY id LIMIT 1");$reversalQuery->execute([$id]);$existingReversal=$reversalQuery->fetch();if($existingReversal):?><section class="panel"><h2>Existing reversal operation</h2><p><?=e($existingReversal['kind'])?> · <?=e($existingReversal['state'])?></p><p>Another reversal cannot be submitted from this order. Verify the original operation in provider reporting; an uncertain result must not be submitted again.</p></section><?php endif;if($order['payment_state']==='paid'&&!$existingReversal):?><section class="panel"><h2>Full payment reversal</h2><p>Void before settlement, or refund after settlement. Amount: <strong><?=e(Money::format((int)$order['total_cents']))?></strong>. Stock is not automatically returned.</p><form method="post" class="form-stack"><?=csrf_field()?><input type="hidden" name="nonce" value="<?=e(bin2hex(random_bytes(32)))?>"><label class="field-stack">Current owner password<input name="owner_password" type="password" autocomplete="current-password" required></label><label class="checkbox-label"><input type="checkbox" name="confirm_reversal" value="1" required>I confirm this full-amount reversal.</label><button class="button secondary" name="action" value="void">Void unsettled payment</button><button class="button outline" name="action" value="refund">Refund settled payment</button></form><p class="small muted">One reversal operation is permitted per order in this checkpoint. Rejected, uncertain, partial or externally initiated reversals require provider review; never blindly retry.</p></section><?php endif;?>
